<script lang="ts">
  import { onMount } from 'svelte';
  import Arrow from './lib/Arrow.svelte';
  import { api } from './lib/api';
  import { buildings, conditions, communityStatus, recentReports, feedbackFor, age } from './lib/model';
  import { survey, question, percent } from './lib/survey';
  import type { BuildingId, Condition, Feed, Report } from './lib/types';
  const oit='https://atlas.utdallas.edu/TDClient/30/Portal/Requests/Service/170/CometNet-Wi-Fi';
  let view=$state<'map'|'research'>('map');
  let layer=$state<'community'|'survey'>('community');
  let selected=$state<BuildingId>('ecsw');
  let search=$state(''), filter=$state('all'), minutes=$state(60);
  let feed=$state<Feed>({reports:[],serverTime:Date.now(),seeded:false});
  let clock=$state(Date.now()), lastRefresh=$state(0), connection=$state<'loading'|'online'|'offline'>('loading');
  let toast=$state(''), toastTimer:ReturnType<typeof setTimeout>, busy=$state(false), formError=$state('');
  let dialog:HTMLDialogElement;
  let formBuilding=$state<BuildingId>('ecsw'), condition=$state<Condition>('slow'), area=$state(''), note=$state('');
  let submitted=$state<Report|null>(null);
  let pendingConfirmation=$state('');
  const current=$derived(buildings.find(b=>b.id===selected)!);
  const recent=$derived(recentReports(feed.reports,clock,minutes));
  const locationReports=$derived(recent.filter(r=>r.building===selected));
  const status=$derived(communityStatus(locationReports));
  const incidentCounts:Record<BuildingId,number>={ecsw:30,ecsn:15,atec:3,jsom:2};
  const visible=$derived(buildings.filter(b=>`${b.code} ${b.name}`.toLowerCase().includes(search.toLowerCase())&&(layer==='survey'||filter==='all'||(filter==='issues'?['slow','down'].includes(buildingStatus(b.id)):buildingStatus(b.id)==='good'))));
  const alternative=$derived(buildings.filter(b=>b.id!==selected&&buildingStatus(b.id)==='good').sort((a,b)=>Math.hypot(a.x-current.x,a.y-current.y)-Math.hypot(b.x-current.x,b.y-current.y))[0]);
  const latest=$derived(locationReports.find(r=>r.condition===status));
  const feedback=$derived(submitted?feedbackFor(submitted,feed.reports,clock):null);
  const activeSpots=$derived(buildings.filter(b=>recent.some(r=>r.building===b.id)).length);
  function buildingStatus(id:BuildingId){return communityStatus(recent.filter(r=>r.building===id));}
  function accept(next:Feed){feed=next;clock=next.serverTime;lastRefresh=Date.now();connection='online';}
  async function refresh(){try{accept(await api.feed());}catch{connection='offline';}}
  function notify(text:string){toast=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast='',6000);}
  function openReport(){formBuilding=selected;formError='';submitted=null;dialog.showModal();}
  async function submit(event:SubmitEvent){
    event.preventDefault();if(busy)return;busy=true;formError='';
    try{const result=await api.report({building:formBuilding,condition,area,note});accept(result.feed);selected=formBuilding;layer='community';filter='all';search='';submitted=result.report;area='';note='';}
    catch(e){formError=e instanceof Error?e.message:'Could not send your report. Your note has been kept.';}finally{busy=false;}
  }
  async function confirm(report:Report){if(pendingConfirmation)return;pendingConfirmation=report.id;try{accept(await api.confirm(report.id));notify('Your confirmation was added. Other visitors will see it on their next refresh.');}catch(e){notify(e instanceof Error?e.message:'Unable to confirm right now.');}finally{pendingConfirmation='';}}
  async function clearMine(){try{accept(await api.clearMine());notify('Your reports and confirmations were cleared. Other contributions remain.');}catch{notify('Unable to clear your contributions. Please try again.');}}
  function download(kind:'survey'|'reports'){
    const data=kind==='survey'?survey:{description:'Unverified demo observations. Sample entries are synthetic, not survey records.',exportedAt:new Date().toISOString(),reports:feed.reports};
    const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));
    const link=document.createElement('a');link.href=url;link.download=`cometpulse-${kind}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  function selectBuilding(id:BuildingId){selected=id;submitted=null;}
  onMount(()=>{void refresh();const poll=setInterval(refresh,10000),tick=setInterval(()=>clock+=1000,1000);return()=>{clearInterval(poll);clearInterval(tick);clearTimeout(toastTimer);};});
</script>

